import asyncio
import datetime
from typing import Callable, Awaitable
from app.contracts.optimization import OptimizationRequest, OptimizationResult
from app.contracts.events import RunEvent

SAMPLE_OPTIMIZED_CPP = """// CompilerAI Optimization Studio - Demo Optimized Output
// Note: Generated by MockOptimizationAgent (Milestone 1 Demo Mode)
#include <stdio.h>
#include <stdlib.h>

static int globalCounter = 0; // Initialized static global

int sumArray(const int* __restrict__ arr, int n) {
    int sum = 0; // Initialized local accumulator
    int i = 0;
    
    // Loop unrolled 4x with strict bounds check (i < n)
    for (; i <= n - 4; i += 4) {
        sum += arr[i] + arr[i+1] + arr[i+2] + arr[i+3];
    }
    for (; i < n; i++) {
        sum += arr[i];
    }
    return sum;
}

int main(void) {
    const int data[5] = {10, 20, 30, 40, 50};
    
    // Hoisted invariants and pre-computed loop bounds
    int result = 0;
    for (int i = 0; i < 5; ++i) {
        result += data[i] * 5; // Simplified redundant nested accumulation
    }
    
    int total = sumArray(data, 5);
    printf("Total: %d, Result: %d\\n", total, result);
    return 0;
}
"""

class MockOptimizationAgent:
    """
    Deterministic mock implementation of the Optimization Agent.
    Implements realistic event streaming and transformation reporting for Milestone 1.
    """

    async def execute(
        self,
        request: OptimizationRequest,
        emit: Callable[[RunEvent], Awaitable[None]],
    ) -> OptimizationResult:
        start_time = datetime.datetime.now(datetime.timezone.utc)
        seq = 1

        async def send_event(event_type: str, status: str, message: str, data: dict = None):
            nonlocal seq
            event = RunEvent(
                run_id=request.run_id,
                seq=seq,
                type=event_type,
                agent="optimization",
                stage="optimization",
                status=status,
                timestamp=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                message=message,
                data=data or {},
            )
            seq += 1
            await emit(event)

        # 1. Agent started
        await send_event(
            "agent_started",
            "running",
            "Optimization Agent started analysis and AST transformation pass",
            {"inference_mode": request.inference_mode.value, "language": request.language},
        )
        await asyncio.sleep(0.15)

        # Scripted failure testing support
        if request.options.get("mock_failure") or "FAIL_OPTIMIZATION" in request.source_code:
            await send_event(
                "agent_log",
                "running",
                "Optimization error: Failed during AST simplification pass (Scripted failure)",
            )
            await send_event(
                "agent_failed",
                "failed",
                "Optimization Agent encountered an unrecoverable syntax/semantic analysis error",
                {"error": "Simulated syntax or AST lowering failure"},
            )
            return OptimizationResult(
                run_id=request.run_id,
                status="failed",
                optimized_code=None,
                transformations=[],
                metrics={},
                raw_result={"error": "Simulated optimization failure"},
                diagnostics=["Optimization pass aborted: syntax/semantic error encountered in AST lowering."],
                duration_ms=150,
                is_demo=True,
            )

        # 2. Progress & Logs
        await send_event("agent_progress", "running", "Parsing AST and computing Control Flow Graph (CFG)...", {"progress": 30})
        await asyncio.sleep(0.15)

        await send_event(
            "agent_log",
            "running",
            "Detected uninitialized local variable 'sum' in function 'sumArray' - inserted zero initialization",
        )
        await send_event(
            "agent_log",
            "running",
            "Identified off-by-one boundary condition in loop (i <= n -> i < n) - corrected loop guard",
        )
        await asyncio.sleep(0.15)

        await send_event("agent_progress", "running", "Applying loop optimizations: unrolling 4x and vectorization hint...", {"progress": 70})
        await asyncio.sleep(0.15)

        await send_event(
            "agent_log",
            "running",
            "Simplified redundant nested accumulation in main(): replaced O(N^2) inner loop with invariant multiplication",
        )

        # Scripted missing code scenario for pipeline test
        if request.options.get("mock_missing_code"):
            await send_event(
                "agent_completed",
                "completed",
                "Optimization finished but produced no runnable output artifact",
            )
            return OptimizationResult(
                run_id=request.run_id,
                status="completed",
                optimized_code=None,
                transformations=["Pass completed with no emitted code artifact"],
                metrics={},
                raw_result={"warning": "No code emitted"},
                diagnostics=["No output artifact generated."],
                duration_ms=450,
                is_demo=True,
            )

        # 3. Successful transformation
        end_time = datetime.datetime.now(datetime.timezone.utc)
        duration_ms = int((end_time - start_time).total_seconds() * 1000)

        transformations = [
            "Fixed uninitialized variable 'sum' with explicit 0 initialization",
            "Corrected loop boundary condition from (i <= n) to (i < n)",
            "Applied 4x loop unrolling with tail cleanup for sumArray",
            "Reduced nested invariant loop accumulation in main() to direct scaling",
            "Added restrict qualifier to array pointer for memory aliasing disambiguation",
        ]

        metrics = {
            "estimated_speedup": "1.85x",
            "instructions_reduced": "38%",
            "memory_accesses_saved": 15,
            "loops_unrolled": 1,
            "invariants_hoisted": 1,
        }

        # Emit artifact event
        await send_event(
            "agent_artifact",
            "running",
            "Optimized source code artifact generated",
            {"language": request.language, "lines": len(SAMPLE_OPTIMIZED_CPP.splitlines())},
        )
        await asyncio.sleep(0.1)

        # Agent completed
        await send_event(
            "agent_completed",
            "completed",
            "Optimization Agent completed successfully (Mock Demo)",
            {"duration_ms": duration_ms, "transformations_count": len(transformations)},
        )

        return OptimizationResult(
            run_id=request.run_id,
            status="completed",
            optimized_code=SAMPLE_OPTIMIZED_CPP,
            transformations=transformations,
            metrics=metrics,
            raw_result={
                "agent": "MockOptimizationAgent",
                "demo": True,
                "transformations": transformations,
                "metrics": metrics,
            },
            diagnostics=[
                "[DEMO MODE] This result was produced by MockOptimizationAgent for development/testing.",
                "Inference mode selector was received but real LLM/heuristic integration will occur in a later milestone.",
            ],
            duration_ms=duration_ms,
            is_demo=True,
        )
